    lines: [
      { sku: 'WORKSHOP-DAY', qty: 2 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'ICON-SET', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].vatRate, 0);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 21);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 100 }), 100);
  assert.equal(lineTotal({ qty: 10, unitPrice: 1 }), 10);
});

test('lineTotal handles single unit', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
});

test('lineTotal handles large quantities', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 8500 }), 8500000);
});

test('invoiceTotals returns correct subtotal and total for single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals returns correct subtotal and total for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 10, unitPrice: 9500 },
      { qty: 2, unitPrice: 50 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500 + 95000 + 100);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals works with real invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 5 * 8500 + 10 * 9500);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals returns subtotal of zero for empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500 }],
  };

  const original = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), original);
});

test('addLine adds a new line to an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const invoice = result.value;
  assert.equal(invoice.lines.length, 1);

  const updated = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
