  const added = addLine(invoice, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(added.ok, true);
  invoice = added.value;
  assert.equal(invoice.lines.length, 2);

  const removed = removeLine(invoice, 'DES-HOUR');
  assert.equal(removed.ok, true);
  invoice = removed.value;
  assert.equal(invoice.lines.length, 1);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
});
